-- Esquema de la base de datos (se ejecuta antes de data.sql cuando la base de datos es nueva)
CREATE TABLE IF NOT EXISTS users (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password TEXT NOT NULL, authority INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS players (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, firstname TEXT NOT NULL, lastname TEXT NOT NULL, email TEXT NOT NULL, image TEXT NOT NULL DEFAULT 'default_profile.png', user_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS news (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS games (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, history_id INTEGER NOT NULL, current_chapter_id INTEGER NOT NULL DEFAULT 0, current_scene_id INTEGER NOT NULL DEFAULT 0, current_decision_id INTEGER NOT NULL DEFAULT 0, player_id INTEGER NOT NULL, start_date DATE NOT NULL, state TEXT NOT NULL DEFAULT 'IN_PROGRESS', points_m INTEGER NOT NULL DEFAULT 0, points_r INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS chapters (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, chapter_number TEXT NOT NULL, image_path TEXT, required_relationship_state TEXT, history_id INTEGER);
CREATE TABLE IF NOT EXISTS player_chapter_state (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, player_id INTEGER NOT NULL, chapter_id INTEGER NOT NULL, game_id INTEGER NOT NULL, played BOOLEAN NOT NULL DEFAULT false, unlocked BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS scenes (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, chapter_id INTEGER NOT NULL, background_image TEXT, scene_order INTEGER);
CREATE TABLE IF NOT EXISTS options (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, decision_id INTEGER NOT NULL, text TEXT NOT NULL, points_m INTEGER DEFAULT 0, points_r INTEGER DEFAULT 0, next_decision_id INTEGER, required_psychological_state TEXT);
CREATE TABLE IF NOT EXISTS decisions (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, scene_id INTEGER NOT NULL, decision_order INTEGER NOT NULL, character_id INTEGER, dialogue TEXT);
CREATE TABLE IF NOT EXISTS characters (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, image_path TEXT);
CREATE TABLE IF NOT EXISTS player_decision_state (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, player_id INTEGER NOT NULL, game_id INTEGER NOT NULL, decision_id INTEGER NOT NULL, option_id INTEGER NOT NULL, completed BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS historys (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, published BOOLEAN NOT NULL DEFAULT false, image_path TEXT NOT NULL, description TEXT NOT NULL);
